def build_vocab(sequence):
    """Sorted vocabulary plus both lookup tables."""
    vocab = sorted(set(sequence))
    char_to_idx = {c: i for i, c in enumerate(vocab)}
    idx_to_char = {i: c for c, i in char_to_idx.items()}
