import torch
import torch.nn as nn


class TitanicMLP(nn.Module):
    def __init__(self):
        super().__init__()
        self.fc1, self.fc2, self.fc3 = nn.Linear(7, 64), nn.Linear(64, 32), nn.Linear(32, 1)

    def forward(self, x):
        x = torch.relu(self.fc2(torch.relu(self.fc1(x))))
        return torch.sigmoid(self.fc3(x)).squeeze(1)       # shape (batch,) to match 1-D labels


def accuracy(model, X, y):
    with torch.no_grad():
        return ((model(X) > 0.5).float() == y).float().mean().item()


def grid_search(X_tr, y_tr, X_va, y_va, lrs, epochs_list, seed=0):
    """Train one fresh model per (lr, epochs) pair; judge each on validation data only."""
    results = []
    for lr in lrs:
        for epochs in epochs_list:
            torch.manual_seed(seed)                           # same start for every configuration
            model = TitanicMLP()
            opt = torch.optim.Adam(model.parameters(), lr=lr)
            loss_fn = nn.BCELoss()
            for _ in range(epochs):
                opt.zero_grad()
                loss_fn(model(X_tr), y_tr).backward()
                opt.step()
            results.append({'lr': lr, 'epochs': epochs, 'val_acc': accuracy(model, X_va, y_va)})
    return sorted(results, key=lambda r: (-r['val_acc'], r['epochs'], r['lr']))
