import heapq


def build(words):
    root = {'children': {}, 'count': 0, 'end': False}
    for w in words:
        node = root
        for ch in w:
            node = node['children'].setdefault(ch, {'children': {}, 'count': 0, 'end': False})
            node['count'] += 1
        node['end'] = True
    return root


def ucs_with_costs(root, prefix):
    """(word, total cost) pairs under prefix, cheapest first; an edge into a node costs 1 / (words that pass through that node).
    Ties are broken alphabetically."""
    node = root
    for ch in prefix:
        if ch not in node['children']:
            return []
        node = node['children'][ch]
    heap = [(0.0, prefix, id(node), node)]
    out = []
    while heap:
        cost, text, _, cur = heapq.heappop(heap)
        if cur['end']:
            out.append((text, round(cost, 4)))
        for ch, child in cur['children'].items():
            heapq.heappush(heap, (cost + 1.0 / child['count'], text + ch, id(child), child))
    return out
```

