from collections import Counter, defaultdict


def create_frequency_tables(document, n):
    """List of n tables; table k-1 maps a context of length k-1 to a Counter of the next characters (k = 1..n).
    Table 0 has the empty context '' and counts single characters. Windows that do not fit are skipped."""
    tables = [defaultdict(Counter) for _ in range(n)]
    for k in range(1, n + 1):
        for i in range(len(document) - k + 1):
            window = document[i:i + k]
            tables[k - 1][window[:-1]][window[-1]] += 1
    return tables


def probability(tables, context, char):
    """P(char | context) = count(context + char) / count(context followed by anything); 0.0 if the context is unseen."""
    k = len(context)
    if k >= len(tables):
        raise ValueError('context longer than the model supports')
    row = tables[k].get(context)
    if not row:
        return 0.0
    return row[char] / sum(row.values())


def review_cases():
    """Cases that a code review should try: n larger than the text, empty text, repeated characters."""
    return {
        'n_larger_than_text': create_frequency_tables('ab', 5),
        'empty_text': create_frequency_tables('', 2),
        'repeated': create_frequency_tables('aaaa', 2),
    }
```

On the text `abab` with n = 2, table 0 holds the single-character counts (`a`: 2, `b`: 2), and table 1 maps each one-character context to what follows it: after `a` always `b` (twice), after `b` only `a` (once, because the text ends on `b`). So P(b | a) = 1.0, and for an unseen context the function returns 0.0 instead of crashing. A reviewer should always try three edge cases: **n longer than the text** (the extra tables are empty, but the function must still return n tables), an **empty text**, and **repeated characters**. These are exactly the cases that a step-by-step read of the logic tends to skip, and each one is a one-line test.

