import torch


def rnn_step_shapes(batch, emb, hidden):
    """Shapes needed for h_t = tanh(x_t W_e^T + h_{t-1} W_h + b) written with torch.mm."""
    return {'x_t': (batch, emb), 'W_e': (hidden, emb), 'W_h': (hidden, hidden), 'h_prev': (batch, hidden), 'b': (hidden,)}


def step_correct(batch=4, emb=3, hidden=5, seed=0):
    g = torch.Generator().manual_seed(seed)
    s = rnn_step_shapes(batch, emb, hidden)
    x_t = torch.randn(s['x_t'], generator=g)
    W_e = torch.randn(s['W_e'], generator=g)
    W_h = torch.randn(s['W_h'], generator=g)
    h_prev = torch.zeros(s['h_prev'])
    b = torch.zeros(s['b'])
    return torch.tanh(torch.mm(x_t, W_e.t()) + torch.mm(h_prev, W_h) + b)


def check_matmul(a_shape, b_shape):
    """Message for a failed torch.mm, or the result shape."""
    if len(a_shape) != 2 or len(b_shape) != 2:
        return 'torch.mm needs two 2-D tensors'
    if a_shape[1] != b_shape[0]:
        return f'cannot multiply {a_shape} by {b_shape}: inner sizes {a_shape[1]} and {b_shape[0]} differ'
    return (a_shape[0], b_shape[1])


def wrong_orientation_error(batch=4, emb=3, hidden=5):
    """Forgetting the transpose: x_t (batch, emb) @ W_e (hidden, emb) fails unless emb == hidden."""
    x = torch.zeros(batch, emb)
    W = torch.zeros(hidden, emb)
    try:
        torch.mm(x, W)
    except RuntimeError as e:
        return str(e)
    return None
```

A matrix product `A @ B` needs the **inner sizes to match**: (batch, emb) times (emb, hidden) is fine, but (batch, emb) times (hidden, emb) fails unless `emb == hidden`, which is the usual 'mat1 and mat2 shapes cannot be multiplied' error. If `W_e` is stored as (hidden, emb), the input has to be multiplied by `W_e.t()`. Write the shape of every operand next to each line, compare them with `print(x.shape)`, and test one step with tiny sizes (batch 4, embedding 3, hidden 5) before running the whole training.

