            if node is None:
                return None
        return node

    def suggest_bfs(self, prefix):
        """Look the prefix up first, then search breadth-first from that node."""
        start = self._find(prefix)
        if start is None:
            return []
        out, queue = [], deque([(start, prefix)])
        while queue:
            node, word = queue.popleft()
            if node.is_word:
                out.append(word)
            for ch in sorted(node.children):
                queue.append((node.children[ch], word + ch))
        return out

    def suggest_ucs(self, prefix):
        """Edge cost = 1 / (number of words through the child), so frequent continuations are cheaper.
        Fractions avoid floating-point ties; equal costs are broken by the word itself."""
        start = self._find(prefix)
        if start is None:
            return []
        out, frontier = [], [(Fraction(0), prefix, start)]
        while frontier:
            cost, word, node = heapq.heappop(frontier)
            if node.is_word:
                out.append(word)
            for ch, child in node.children.items():
                heapq.heappush(frontier, (cost + Fraction(1, child.count), word + ch, child))
        return out
```

The heap entries are `(cost, word, node)`, so two entries never tie all the way to the `Node`, which avoids the 'Node < Node' TypeError. Repeated words in the document raise the counts, which is what makes frequent words cheaper.

