def build_trie(words):
    root = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
    return root


def to_mermaid(words):
    """Mermaid 'graph TD' text. The id of a node is 'N' + its path (unique), and the label in brackets is its letter."""
    root = build_trie(words)
    lines = ['graph TD;']

    def walk(node, path):
        for ch, child in node.items():
            new = path + ch
            parent = 'ROOT' if not path else 'N' + path
            lines.append(f'    {parent}-->N{new}[{ch.upper()}]')
            walk(child, new)

    walk(root, '')
    return '\n'.join(lines)
