```python
import collections


def create_frequency_tables(document, n):
    """Table k (0-based) counts every substring of length k + 1."""
    tables = [collections.Counter() for _ in range(n)]
    for size in range(1, n + 1):
        for start in range(len(document) - size + 1):
            tables[size - 1][document[start:start + size]] += 1
    return tables


def calculate_probability(sequence, char, tables):
    """P(char | the longest context of the sequence that has been seen), backing off to shorter contexts."""
    for k in range(min(len(sequence), len(tables) - 1), -1, -1):
        context = sequence[len(sequence) - k:] if k else ''
        total = sum(count for gram, count in tables[k].items() if gram[:-1] == context)
        if total:
            return tables[k][context + char] / total
    return 0.0


def predict_next_char(sequence, tables, vocabulary):
    best, best_p = None, -1.0
    for c in vocabulary:
        p = calculate_probability(sequence, c, tables)
        if p > best_p:
            best, best_p = c, p
    return best
```

Table `k` holds grams of length `k + 1`, so a context of `k` letters is looked up in table `k`. The loop starts with the longest context that the tables allow and **backs off** one letter at a time until it finds a context that appears in the training text. That is what prevents the 'every probability is 0' failure on unseen contexts. Starting `best_p` at -1 means that even a probability of 0 can be chosen, and the strict `>` keeps the first character on a tie.

```python
def probability_table(tables, k):
    """Reference solution: {prefix: {next_char: probability}} for context length k.
    k = 0 gives the unigram distribution under the empty prefix ()."""
    if k == 0:
        total = sum(tables[0].values())
        return {(): {c: n / total for c, n in tables[0].items()}}
    return {prefix: {c: n / sum(counts.values()) for c, n in counts.items()}
            for prefix, counts in tables[k].items()}


def to_markdown(table, digits=4):
    """Render a probability table (as returned above) as a markdown table."""
    chars = sorted({c for row in table.values() for c in row})
    lines = ['| prefix | ' + ' | '.join(chars) + ' |',
             '|---|' + '---|' * len(chars)]
    for prefix in sorted(table):
        row = table[prefix]
        cells = [f'{row.get(c, 0):.{digits}f}' for c in chars]
        lines.append(f"| {''.join(prefix) or '(none)'} | " + ' | '.join(cells) + ' |')
    return '\n'.join(lines)
```

Both functions take the list of tables built by `create_frequency_tables`, so the same code works for any `n`. `to_markdown` writes `0.0000` for unseen next characters, which is what lets students spot structural zeros like P(b|b) = 0.

