import heapq
import math


class Node:
    def __init__(self):
        self.children = {}
        self.count = 0           # number of inserted words that pass through this node
        self.is_word = False


class ProbTrie:
    def __init__(self, document=''):
        self.root = Node()
        for word in document.split():
            node = self.root
            node.count += 1
            for ch in word:
                node = node.children.setdefault(ch, Node())
                node.count += 1
            node.is_word = True

    def _find(self, prefix):
        node = self.root
        for ch in prefix:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

    def suggest_ucs(self, prefix):
        """Uniform-cost search where stepping to a child costs -log(P(child | parent)).
        A word's total cost is -log of its probability among words that share the prefix."""
        start = self._find(prefix)
        if start is None:
            return []
        out, frontier = [], [(0.0, prefix, start)]
        while frontier:
            cost, word, node = heapq.heappop(frontier)
            if node.is_word:
                out.append((word, cost))
            for ch, child in node.children.items():
                step = -math.log(child.count / node.count)
                heapq.heappush(frontier, (cost + step, word + ch, child))
        return out
```

The root's `count` is the number of words inserted, so the first step from the root has probability `child.count / root.count`. Costs are floats, so two words with the same true cost can differ in the last digits. The tests below therefore use `pytest.approx`.

```python
import torch
from torch.utils.data import Dataset


class CharDataset(Dataset):
    def __init__(self, data, sequence_length, stride):
        self.sequences, self.targets = [], []
        for i in range(0, len(data) - sequence_length, stride):
            self.sequences.append(data[i:i + sequence_length])
            self.targets.append(data[i + 1:i + sequence_length + 1])     # the same window shifted by one character

    def __len__(self):
        return len(self.sequences)

    def __getitem__(self, idx):
        return torch.tensor(self.sequences[idx]), torch.tensor(self.targets[idx])


def expected_windows(n_chars, sequence_length, stride):
    """Number of windows: starts 0, stride, 2*stride, ... while start < n_chars - sequence_length."""
    if n_chars <= sequence_length:
        return 0
    return (n_chars - sequence_length - 1) // stride + 1
```

Each training example is a window of `sequence_length` characters, and its target is the **same window shifted one character to the right**, so at every position the model is asked to predict the next character. The loop stops at `len(data) - sequence_length` so that the shifted target never runs past the end of the data. A smaller stride gives more, heavily overlapping windows; a larger stride gives fewer, less overlapping ones.

