def check_conditionals(probs, vocab, tol=1e-9):
    """probs maps (x, given) -> P(x | given). Returns {given: sum of P(x | given) over x} and the contexts that are not 1."""
    sums = {g: sum(probs[(x, g)] for x in vocab) for g in vocab}
    bad = sorted(g for g, s in sums.items() if abs(s - 1.0) > tol)
    return sums, bad


