```python
import heapq
from collections import deque


class Node:
    def __init__(self):
        self.children = {}
        self.is_word = False


class Trie:
    def __init__(self):
        self.root = Node()

    def build_tree(self, document):
        for word in document.split():
            node = self.root
            for ch in word:
                node = node.children.setdefault(ch, Node())
            node.is_word = True

    def _find(self, prefix):
        node = self.root
        for ch in prefix:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

    def suggest_bfs(self, prefix):
        """Breadth-first: shorter completions first; children visited in alphabetical order."""
        start = self._find(prefix)
        if start is None:
            return []
        out, queue = [], deque([(start, prefix)])
        while queue:
            node, word = queue.popleft()
            if node.is_word:
                out.append(word)
            for ch in sorted(node.children):
                queue.append((node.children[ch], word + ch))
        return out

    def suggest_ucs(self, prefix):
        """Uniform cost: edge cost = alphabet position of the letter (a=1 ... z=26);
        equal total costs are broken by the word itself, which keeps the order deterministic."""
        start = self._find(prefix)
        if start is None:
            return []
        out, frontier = [], [(0, prefix, start)]
        while frontier:
            cost, word, node = heapq.heappop(frontier)
            if node.is_word:
                out.append(word)
            for ch, child in node.children.items():
                heapq.heappush(frontier, (cost + ord(ch) - 96, word + ch, child))
        return out
```

The heap entries are `(cost, word, node)`. Because two different paths always have different words, Python never has to compare two `Node` objects, which avoids the 'Node < Node' TypeError students often hit. The prefix itself is returned if it is a word, which the tests below assume.

