        self.rng = random.Random(seed)
        self.suggest = self.suggest_random          # default; reassign to suggest_bfs to switch
        self.build_tree(document)

    def build_tree(self, document):
        for word in document.split():
            node = self.root
            for ch in word:
                node = node.children.setdefault(ch, Node())
            node.is_word = True

    def _completions(self, prefix):
        node = self.root
        for ch in prefix:
            node = node.children.get(ch)
            if node is None:
                return []
        out, queue = [], deque([(node, prefix)])
        while queue:
            n, text = queue.popleft()
            if n.is_word:
                out.append(text)
            for ch in sorted(n.children):
                queue.append((n.children[ch], text + ch))
        return out

    def suggest_bfs(self, prefix):
        return self._completions(prefix)

    def suggest_random(self, prefix, k=3):
        """Up to k distinct completions chosen at random; a seeded generator keeps tests repeatable."""
        words = self._completions(prefix)
        return self.rng.sample(words, min(k, len(words)))
```

The class stores the chosen strategy in `self.suggest`, so the default (`suggest_random`) can be swapped for `suggest_bfs` (or DFS and UCS) with one assignment. Using `random.Random(seed)` instead of the global generator makes the random baseline repeatable, which a test needs.

