```python
import time
from collections import deque


class Node:
    def __init__(self):
        self.children = {}
        self.is_word = False


def build(words):
    root = Node()
    for w in words:
        node = root
        for ch in w:
            node = node.children.setdefault(ch, Node())
        node.is_word = True
    return root


def _start(root, prefix):
    node = root
    for ch in prefix:
        node = node.children.get(ch)
        if node is None:
            return None
    return node


def dfs_recursive(root, prefix):
    start = _start(root, prefix)
    out = []

    def visit(node, text):
        if node.is_word:
            out.append(text)
        for ch in sorted(node.children):
            visit(node.children[ch], text + ch)

    if start is not None:
        visit(start, prefix)
    return out


def dfs_stack(root, prefix):
    """Same order as dfs_recursive: push children in reverse so the smallest letter is popped first."""
    start = _start(root, prefix)
    if start is None:
        return []
    stack, out = [(start, prefix)], []
    while stack:
        node, text = stack.pop()
        if node.is_word:
            out.append(text)
        for ch in sorted(node.children, reverse=True):
            stack.append((node.children[ch], text + ch))
    return out


def front_pop_cost(n):
    """Time n pops from the front of a list versus a deque (the list is quadratic)."""
    lst, dq = list(range(n)), deque(range(n))
    t0 = time.perf_counter()
    while lst:
        lst.pop(0)
    t1 = time.perf_counter()
    while dq:
        dq.popleft()
    t2 = time.perf_counter()
    return t1 - t0, t2 - t1
```

The two versions visit nodes in the same order. The stack version pushes children in **reverse** order so that the smallest letter is popped first, which is what the recursion does naturally. A stack should pop from the **end** (`pop()`), which is constant time; popping from the front of a list (`pop(0)`) shifts every other element, so it is slow for large inputs, and `deque.popleft()` is the right tool when you need a front-pop (as in BFS).

