import heapq
from collections import deque


class Node:
    def __init__(self):
        self.children = {}
        self.is_word = False


class Trie:
    def __init__(self):
        self.root = Node()

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, Node())
        node.is_word = True

    def _start(self, prefix):
        node = self.root
        for ch in prefix:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

    def suggest_bfs(self, prefix):
        start = self._start(prefix)
        if start is None:
            return []
        out, queue = [], deque([(start, prefix)])
        while queue:
            node, text = queue.popleft()
            if node.is_word:
                out.append(text)
            for ch in sorted(node.children):
                queue.append((node.children[ch], text + ch))
        return out

    def suggest_dfs(self, prefix):
        start = self._start(prefix)
        if start is None:
            return []
        out, stack = [], [(start, prefix)]
        while stack:
            node, text = stack.pop()
            if node.is_word:
                out.append(text)
            for ch in sorted(node.children, reverse=True):   # reversed so 'a' is popped before 'b'
                stack.append((node.children[ch], text + ch))
        return out

    def suggest_ucs(self, prefix, cost=None):
        """Cheapest-first: the cost of a word is the sum of the cost of each letter after the prefix."""
        cost = cost or {}
        start = self._start(prefix)
        if start is None:
            return []
        out, heap, tie = [], [(0, prefix, 0, start)], 0
        while heap:
            total, text, _, node = heapq.heappop(heap)
            if node.is_word:
                out.append(text)
            for ch in node.children:
                tie += 1
                heapq.heappush(heap, (total + cost.get(ch, 1), text + ch, tie, node.children[ch]))
        return out
```

All three start from the node reached by following the prefix, not from the root. **BFS** uses a queue, so shorter words come out first. **DFS** uses a stack, so it follows one branch to its end before backing up. **UCS** orders by total path cost. With every letter costing 1, that is the same as BFS (apart from the order of ties), which answers your worry about the outputs being too similar. Give letters different costs and the order changes.

