from collections import deque


class Node:
    def __init__(self):
        self.curr_word = ''        # the text spelled by the path from the root to this node
        self.children = {}
        self.is_word = False


class Autocomplete:
    def __init__(self, document=''):
        self.root = Node()
        self.build_tree(document)

    def build_tree(self, document):
        for word in document.split():
            node, prefix = self.root, ''
            for ch in word:
                prefix += ch                         # the buggy version added to an undefined `curr_word`
                node = node.children.setdefault(ch, Node())
                node.curr_word = prefix
            node.is_word = True

    def _find(self, prefix):
        node = self.root
        for ch in prefix:
            node = node.children.get(ch)            # .get avoids KeyError for unknown prefixes
            if node is None:
                return None
        return node

    def suggest_bfs(self, prefix):
        node = self._find(prefix)
        if node is None:
            return []
        queue, found = deque([node]), []
        while queue:
            cur = queue.popleft()                    # O(1); list.pop(0) is O(n)
            if cur.is_word:
                found.append(cur.curr_word)
            queue.extend(cur.children[c] for c in sorted(cur.children))
        return found

    def suggest_dfs(self, prefix):
        node = self._find(prefix)
        if node is None:
            return []
        stack, found = [node], []
        while stack:
            cur = stack.pop()
            if cur.is_word:
                found.append(cur.curr_word)
            stack.extend(cur.children[c] for c in sorted(cur.children, reverse=True))
        return found


def buggy_build(document):
    """The student's version: curr_word is used before it is defined."""
    for word in document.split():
        for char in word:
            curr_word += char       # noqa: F821  (UnboundLocalError)
```

The student's loop does `curr_word += char`, but `curr_word` was never given a value in that scope, so Python raises an `UnboundLocalError`. The fix is to keep a separate `prefix` string, start it as `''` for each word, and store it on the node. The traversals also use `children.get` (so an unknown prefix returns `[]`) and a `deque` (`popleft` is constant time, whereas `list.pop(0)` shifts every element).

```python
import numpy as np
import pandas as pd
from sklearn.linear_model import LinearRegression

RATINGS = {'bread': 3.0, 'burger': 9.0, 'salad': 4.0, 'sandwich': 8.0}      # true mean rating per category


def make_data(n=400, seed=0):
    rng = np.random.default_rng(seed)
    kind = rng.choice(list(RATINGS), size=n)
    rating = np.array([RATINGS[k] for k in kind]) + rng.normal(0, 0.3, n)
    return pd.DataFrame({'kind': kind, 'rating': rating})


def r2_integer_code(df):
    """One column of integer codes 0..3: implies an order and equal spacing."""
    X = df['kind'].astype('category').cat.codes.to_frame('code')
    return LinearRegression().fit(X, df['rating']).score(X, df['rating'])


def r2_one_hot(df):
    X = pd.get_dummies(df['kind'], dtype=float)
    return LinearRegression().fit(X, df['rating']).score(X, df['rating'])


def r2_one_hot_drop_first(df):
    X = pd.get_dummies(df['kind'], drop_first=True, dtype=float)
    return LinearRegression().fit(X, df['rating']).score(X, df['rating'])
```

Running it shows the effect (R² of about 0.21 for one integer column against about 0.99 for separate 0/1 columns). With only **two** categories, a single 0/1 column carries all of the information, so the two encodings are equivalent. With **more than two**, an integer code forces the model to treat the categories as ordered and equally spaced (bread = 0, burger = 1, salad = 2, sandwich = 3), which is false here, so a straight line through the codes fits poorly. Separate 0/1 columns let each category have its own effect, and dropping one of them loses nothing when the model has an intercept.

