import pandas as pd


def chunk_markdown(df, per_table=8, ndigits=3):
    """Split a wide dataframe into several markdown tables of at most per_table columns, repeating the index in each."""
    cols = list(df.columns)
    tables = []
    for start in range(0, len(cols), per_table):
        part = df[cols[start:start + per_table]]
        header = '| index | ' + ' | '.join(part.columns) + ' |'
        sep = '|' + '---|' * (len(part.columns) + 1)
        rows = []
        for idx in part.index:
            cells = []
            for c in part.columns:
                v = part.at[idx, c]
                if isinstance(v, float):
                    cells.append(f'{v:.{ndigits}f}'.rstrip('0').rstrip('.') if v != int(v) else str(int(v)))
                else:
                    cells.append(str(v))
            rows.append(f'| {idx} | ' + ' | '.join(cells) + ' |')
        tables.append('\n'.join([header, sep] + rows))
    return tables


def check_complete(df, tables):
    """Every column appears in exactly one table and every table has one line per row (plus header and separator)."""
    seen = []
    for t in tables:
        lines = t.split('\n')
        seen.extend(c.strip() for c in lines[0].split('|')[2:-1])
        if len(lines) != len(df) + 2:
            return False
    return seen == list(df.columns)
```

A frame with 35 columns can't be read as a single markdown table, so the function splits it into tables of at most eight columns and repeats the row index in each. Trailing zeros are removed (0.500 becomes 0.5, and 2.000 becomes 2), and the completeness check confirms that every column appears exactly once and that every table has all of its rows. That check is the safeguard that matters when a table is produced by a language model or by hand: counts of rows and columns are easy to verify, and a dropped column is exactly the mistake that a 35-column table invites.

