```python
import heapq


class Node:
    def __init__(self):
        self.children = {}
        self.is_word = False
        self.frequency = 0          # how many words pass through this node


def build_tree(document):
    root = Node()
    for word in document.split():
        node = root
        for ch in word:
            node = node.children.setdefault(ch, Node())
            node.frequency += 1
        node.is_word = True
    return root


def suggest_ucs(root, prefix):
    """Words under prefix, cheapest first. Entering a child costs 1/child.frequency (common continuations are cheap).
    Ties are broken by the word itself so the order is reproducible."""
    node = root
    for ch in prefix:
        if ch not in node.children:
            return []
        node = node.children[ch]
    heap = [(0.0, prefix, node)]
    out = []
    while heap:
        cost, text, cur = heapq.heappop(heap)
        if cur.is_word:
            out.append(text)
        for ch, child in cur.children.items():
            heapq.heappush(heap, (cost + 1.0 / child.frequency, text + ch, child))
    return out
```

For the document `car car car card cap cat`, the prefix `ca` gives `['car', 'cap', 'cat', 'card']`. The costs below `ca` are: `car` = 1/4 = 0.25 (four words pass through `r`), `cap` = 1/1 = 1.0, `cat` = 1.0 and `card` = 0.25 + 1/1 = 1.25. So the common word comes first, the two single-use words tie (and are ordered alphabetically by the heap's second tuple element), and the longer word that rests on a rare final letter comes last. Because the heap compares `(cost, text, node)`, ties never reach the `Node` objects, which can't be compared.

