    lines = ['| ' + ' | '.join(keys) + ' |', '|' + '---|' * len(keys)]
    lines += ['| ' + ' | '.join(cell(c[k]) for k in keys) + ' |' for c in rows]
    return '\n'.join(lines)


def parse_loose_json(text):
    """A pasted list of objects without the outer brackets: wrap it and parse."""
