```python
import math

import torch


def init_rnn_params(embed_dim, hidden_size, vocab_size, seed=0):
    """Xavier-uniform weights, zero biases. Shapes follow h_t = tanh(x W_e + h W_h + b_h), logits = h W_out + b_out."""
    g = torch.Generator().manual_seed(seed)

    def xavier(rows, cols):
        bound = math.sqrt(6.0 / (rows + cols))
        return (torch.rand(rows, cols, generator=g) * 2 - 1) * bound

    params = {
        'W_e': xavier(embed_dim, hidden_size),
        'W_h': xavier(hidden_size, hidden_size),
        'b_h': torch.zeros(hidden_size),
        'W_out': xavier(hidden_size, vocab_size),
        'b_out': torch.zeros(vocab_size),
    }
    return {k: v.requires_grad_() for k, v in params.items()}


def loss_after_steps(params, x_embed, targets, steps, lr=0.5):
    """Plain gradient descent on cross-entropy; returns the loss before and after."""
    def loss():
        h = torch.zeros(x_embed.shape[0], params['W_h'].shape[0])
        total = 0.0
        for t in range(x_embed.shape[1]):
            h = torch.tanh(x_embed[:, t] @ params['W_e'] + h @ params['W_h'] + params['b_h'])
            total = total + torch.nn.functional.cross_entropy(h @ params['W_out'] + params['b_out'], targets[:, t])
        return total / x_embed.shape[1]

    first = loss().item()
    for _ in range(steps):
        l = loss()
        for p in params.values():
            p.grad = None
        l.backward()
        with torch.no_grad():
            for p in params.values():
                p -= lr * p.grad
    return first, loss().item()
```

The weights are **not** looked up or calculated by hand. They start as small random numbers (Xavier-uniform here, which scales the range by the layer's size), the biases start at zero, and training then adjusts all of them by gradient descent. Random, unequal starting values matter: if every weight started equal, every hidden unit would learn the same thing.

