import torch
import torch.nn as nn
from sklearn.neural_network import MLPClassifier

ACTIVATIONS = {'relu': nn.ReLU, 'tanh': nn.Tanh, 'sigmoid': nn.Sigmoid}


def build_mlp(sizes, activations):
    """sizes = [in, h1, h2, ..., out]; one activation name per HIDDEN layer (len(sizes) - 2 of them)."""
    if len(activations) != len(sizes) - 2:
        raise ValueError('need one activation per hidden layer')
    layers = []
    for i, act in enumerate(activations):
        layers += [nn.Linear(sizes[i], sizes[i + 1]), ACTIVATIONS[act]()]
    layers.append(nn.Linear(sizes[-2], sizes[-1]))
    return nn.Sequential(*layers)


def sklearn_activation(model_params):
    """MLPClassifier takes ONE activation string for all hidden layers."""
    return MLPClassifier(**model_params).activation
