def elide(df, first=4, last=3, marker='...'):
    """Keep the first and last few columns and put a single marker column between them."""
    if len(df.columns) <= first + last:
        return df.copy()
    out = pd.concat([df.iloc[:, :first], pd.DataFrame({marker: marker}, index=df.index), df.iloc[:, -last:]], axis=1)
    return out


def md_table(df, ndigits=3):
    def cell(v):
        if isinstance(v, bool):
            return str(v)
        if isinstance(v, float):
            return f'{v:.{ndigits}f}'
        return str(v)
    lines = ['| ' + ' | '.join(map(str, df.columns)) + ' |', '|' + '|'.join('---' for _ in df.columns) + '|']
    lines += ['| ' + ' | '.join(cell(v) for v in row) + ' |' for row in df.itertuples(index=False)]
    return '\n'.join(lines)
```

