from collections import deque


class Node:
    def __init__(self):
        self.children = {}
        self.is_word = False


def build_tree(words):
    root = Node()
    for w in words:
        n = root
        for ch in w:
            n = n.children.setdefault(ch, Node())
        n.is_word = True
    return root


def suffixes_bfs(root, prefix):
    """What a first attempt often returns: only the endings that follow the prefix."""
    node = root
    for ch in prefix:
        if ch not in node.children:
            return []
        node = node.children[ch]
    out, q = [], deque([('', node)])
    while q:
        tail, cur = q.popleft()
        if cur.is_word:
            out.append(tail)
        for ch, child in cur.children.items():
            q.append((tail + ch, child))
    return out


def complete_words(root, prefix):
    """Full words: prefix + each ending. A prefix that is itself a word returns the prefix as its own ending ''."""
    return [prefix + tail for tail in suffixes_bfs(root, prefix)]
```

With the words `car, card, care, cat` and the prefix `ca`, the endings come out as `['r', 't', 'rd', 're']` (level by level) and the full words as `['car', 'cat', 'card', 'care']`. A student who complains that the method 'gives me the ending of the prefix typed in, not the full word' has built the **tail** while walking down from the prefix node but forgot to put the prefix back at the front. Either carry the whole text in the queue from the start (`prefix` instead of `''`), or join `prefix + tail` at the end, as here.

