The words 'cat', 'car' and 'card' share the nodes c and a. That's why this structure is a **trie** rather than a binary tree: each node has up to one child per letter, so it needs a dictionary of children instead of just `left` and `right`.

```python
from collections import Counter
from fractions import Fraction


def counts(text, n):
    return Counter(text[i:i + n] for i in range(len(text) - n + 1))


def cond(text, context, char):
    """P(char | context) from counts; 0 if the context never occurs followed by anything."""
    c_ctx = counts(text, len(context) + 1)
    total = sum(v for g, v in c_ctx.items() if g[:-1] == context)
    return Fraction(c_ctx[context + char], total) if total else Fraction(0)


def joint_probability(text, sequence, order):
    """Chain rule with an n-gram approximation: each character depends on the previous (order - 1) characters.
    The first (order - 1) characters use the shorter contexts available (unigram, then bigram...)."""
    p = Fraction(1)
    for i, ch in enumerate(sequence):
        context = sequence[max(0, i - (order - 1)):i]
        p *= cond(text, context, ch) if context else Fraction(counts(text, 1)[ch], len(text))
    return p
```

Yes, the trigram version is the same chain with a longer memory: P(x1) · P(x2|x1) · P(x3|x1,x2) · P(x4|x2,x3) · ..., so from the third character on, each factor conditions on the **two** previous characters, while the first two factors use the shorter contexts that are available. A bigram model conditions on only one. If any factor is 0 (an unseen transition), the whole joint probability is 0, which is why smoothing or backoff matters.

```python
from collections import deque


class Node:
    def __init__(self):
        self.children = {}
        self.is_word = False


class Autocomplete:
    def __init__(self, parent=None, document=''):
        self.root = Node()
        self.document = document            # keep it: __init__'s parameters disappear when it returns
        for word in document.split():
            self._insert(word)

    def _insert(self, word):
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, Node())
        node.is_word = True

    def suggest_bfs(self, prefix):
        node = self.root
        for ch in prefix:
            node = node.children.get(ch)
            if node is None:
                return []
        out, queue = [], deque([(node, prefix)])
        while queue:
            n, w = queue.popleft()
            if n.is_word:
                out.append(w)
            for ch in sorted(n.children):
                queue.append((n.children[ch], w + ch))
        return out

    def word_count(self):
        return len(self.document.split())       # works because document was stored on self
```

