import pandas as pd


def to_md_table(df, ndigits=2):
    """Render a dataframe as a Markdown table: header row, separator row, one row per line."""
    def cell(v):
        return f'{v:.{ndigits}f}' if isinstance(v, float) else str(v)
    header = '| ' + ' | '.join(map(str, df.columns)) + ' |'
    sep = '|' + '|'.join('---' for _ in df.columns) + '|'
    rows = ['| ' + ' | '.join(cell(v) for v in row) + ' |' for row in df.itertuples(index=False)]
    return '\n'.join([header, sep, *rows])


def table_problems(text):
    """Return a list of reasons why Markdown text will not render as a table."""
    lines = text.strip('\n').split('\n')
    problems = []
    if len(lines) < 3:
        problems.append('header, separator and rows must each be on their own line')
        return problems
    counts = {l.count('|') for l in lines}
    if len(counts) > 1:
        problems.append('rows have different numbers of cells')
    cells = [c.strip() for c in lines[1].strip('|').split('|')]
    if not all(c and set(c) <= set('-:') for c in cells):
        problems.append('second line is not a separator row such as |---|---|')
    return problems
```

The pasted table fails to render because it is all on **one line**: Markdown needs the header, the `|---|` separator row and each data row on separate lines. `table_problems` reports that, a missing separator, and rows with different numbers of cells.

