    """Format x to `sig` significant figures, keeping trailing zeros (0.9671 -> '0.96710')."""
    return format(x, f'#.{sig}g')


def results_table(results, sig=5):
    """results: iterable of (model_name, mean_score, std_score) -> markdown table string."""
    lines = ['| Model | Mean score | Std dev |', '|---|---|---|']
    for name, mean, std in results:
