```python
from collections import deque

def bfs_shortest_path(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    queue = deque([(start[0], start[1], 0)])
    visited = {start}
    while queue:
        r, c, dist = queue.popleft()
        if (r, c) == goal:
            return dist
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0 and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, dist + 1))
    return -1
```

```python
from collections import Counter, defaultdict


def train_bigrams(text):
    words = text.lower().split()
    table = defaultdict(Counter)
    for a, b in zip(words, words[1:]):
        table[a][b] += 1
    return table


def next_word(table, word):
    """Most frequent follower; ties go to the alphabetically first word; None if the word was never seen."""
    followers = table.get(word.lower())
    if not followers:
        return None
    best = max(followers.values())
    return min(w for w, c in followers.items() if c == best)


def complete(table, prompt, k=3):
    """Extend the prompt by up to k words, stopping early if the last word has no known follower."""
    words = prompt.lower().split()
    for _ in range(k):
        nxt = next_word(table, words[-1])
        if nxt is None:
            break
        words.append(nxt)
    return ' '.join(words)
```

For the toy text, 'the' is followed by 'cat' twice and 'mat' twice, so the tie goes to the alphabetically first word, 'cat', which makes the output reproducible. Predictions use the **most frequent follower** of the last word (a word-level bigram model). The completion stops early if the last word never appeared in the training text, and the lookup is lower-cased so 'The' and 'the' match. `table.get(...)` is used so that a lookup doesn't add a new key to the defaultdict.

