On data that a straight line can separate, all three classifiers do well (about 0.96 to 0.99 here). On the XOR pattern, where the class depends on the **combination** of the two signs, logistic regression (a linear model) stays near chance (0.63), while the RBF-kernel SVM (0.96) and k-nearest neighbours (0.98) can follow the curved boundary. That's the main practical difference: logistic regression and a linear SVM draw a straight boundary, whereas kNN decides from the labels of nearby points.

Here is an AST visitor that computes McCabe cyclomatic complexity for each function:

```python
class CyclomaticComplexityVisitor(ast.NodeVisitor):
    DECISION_NODES = (
        ast.If, ast.While, ast.For, ast.AsyncFor,
        ast.Assert, ast.ExceptHandler, ast.With, ast.AsyncWith
    )

    def __init__(self, max_complexity=10):
        self.max_complexity = max_complexity
        self.complexity_map = {}

    def visit_FunctionDef(self, node):
        # Base complexity is 1
        complexity = 1
        for child in ast.walk(node):
            if isinstance(child, self.DECISION_NODES):
                complexity += 1
            elif isinstance(child, ast.BoolOp):
                # Each 'and' / 'or' adds a branch condition
                complexity += len(child.values) - 1
        self.complexity_map[node.name] = (complexity, node.lineno)
        self.generic_visit(node)

def test_cyclomatic_complexity():
    with open("student_submission.py", "r", encoding="utf-8") as f:
        tree = ast.parse(f.read())
    visitor = CyclomaticComplexityVisitor(max_complexity=10)
    visitor.visit(tree)

    excessive = [
        (fn, comp, line) for fn, (comp, line) in visitor.complexity_map.items()
        if comp > 10
    ]
    assert not excessive, (
        "Functions exceed maximum allowed cyclomatic complexity of 10. Refactor into smaller helpers:\n" +
        "\n".join([
            f"  - Function '{fn}' (line {line}) has cyclomatic complexity {comp}."
            for fn, comp, line in excessive
        ])
    )
```

