```python
from collections import deque


class TreeNode:
    def __init__(self, value):
        self.value = value
        self.children = []

    def add(self, child):
        self.children.append(child)
        return child


def build_tree(spec):
    """spec is (value, [child specs]) or just a value for a leaf."""
    if not isinstance(spec, tuple):
        return TreeNode(spec)
    value, kids = spec
    node = TreeNode(value)
    for kid in kids:
        node.add(build_tree(kid))
    return node


def bfs(root):
    out, queue = [], deque([root])
    while queue:
        node = queue.popleft()
        out.append(node.value)
        queue.extend(node.children)
    return out


def dfs(root):
    out = []

    def visit(node):
        out.append(node.value)
        for child in node.children:
            visit(child)

    visit(root)
    return out


def height(root):
    return 1 + max((height(c) for c in root.children), default=0)
```

A tree is a node that holds a value and a list of child nodes, and every child is itself a tree. `build_tree` uses that definition recursively. **BFS** keeps a queue, so it visits all nodes at one depth before the next. **DFS** follows a child's subtree to the bottom before the next child. Both visit every node exactly once.

```python
class Node:
    def __init__(self):
        self.children = {}
        self.is_word = False


class Autocomplete:
    def __init__(self, document=''):
        self.root = Node()
        self.build_tree(document)          # forgetting this call leaves the tree empty and the output never changes

    def build_tree(self, document):
        for word in document.split():
            node = self.root
            for char in word:
                if char not in node.children:
                    node.children[char] = Node()
                node = node.children[char]
            node.is_word = True

    def count_nodes(self):
        total, stack = 0, [self.root]
        while stack:
            n = stack.pop()
            total += len(n.children)
            stack.extend(n.children.values())
        return total

    def words(self):
        out = []

        def walk(node, text):
            if node.is_word:
                out.append(text)
            for ch, child in node.children.items():
                walk(child, text + ch)

        walk(self.root, '')
        return out


class BrokenAutocomplete(Autocomplete):
    """Same class, but the constructor never builds the tree: every later method sees an empty tree."""
    def __init__(self, document=''):
        self.root = Node()
        self.document = document
```

The `build_tree` loop itself is correct: for `'to tea ten'`, it creates five nodes (t, to, te, tea, ten) and `words()` returns `['to', 'tea', 'ten']`. A program whose output never changes after editing `build_tree` usually has a different problem: the method is **never called** (the broken subclass stores the document but doesn't build the tree), so every later method sees an empty tree. To diagnose it, print `count_nodes()` right after constructing the object: 0 means that the tree was never built, and the fix is to call `self.build_tree(document)` in the constructor or to call it before using the other methods.

