class NextLetterModel(torch.nn.Module):
    """Stand-in model: puts a large score on the letter after the current one (a->b->c->a)."""
    def forward(self, x, h=None):
        logits = torch.full((x.shape[0], x.shape[1], 3), -10.0)
        for b in range(x.shape[0]):
            for t in range(x.shape[1]):
                logits[b, t, (int(x[b, t]) + 1) % 3] = 10.0
        return logits, h


